/* Loads the cached equity table (data/equity.json, regenerated by
   scripts/equity.ts) and derives each hand class's percentile rank in the
   heads-up equity ranking. Percentile 0 = the best hand (AA), percentile
   just under 100 = the worst. Nothing here recomputes equity at runtime. */

import raw from '../data/equity.json' with { type: 'json' };

// [class, equity] tuples, already sorted descending by the generating
// script. Re-sorted defensively here rather than trusted, since a plain
// object can't hold this order (JS floats integer-like keys like '22' to
// the front regardless of insertion order).
const ranked = [...(raw as [string, number][])].sort((a, b) => b[1] - a[1]);

export const TOTAL_HANDS = ranked.length;

const percentileByHand = new Map<string, number>(ranked.map(([hand], i) => [hand, (i / TOTAL_HANDS) * 100]));
const equityByHand = new Map<string, number>(ranked);

export function equityOf(hand: string): number {
  const e = equityByHand.get(hand);
  if (e === undefined) throw new Error(`unknown hand class: ${hand}`);
  return e;
}

export function percentileOf(hand: string): number {
  const p = percentileByHand.get(hand);
  if (p === undefined) throw new Error(`unknown hand class: ${hand}`);
  return p;
}

export function rankedHands(): [string, number][] {
  return ranked;
}
